json.a1 = 1;
json.a10 = 2;
json.a100 = 3;
json.a2 = 5;
json.a9 = 4;
exit=0

{"x2y": 1, "x10y": 2, "x9y": 3, "x1y": 4}
---
json = {};
json.x10y = 2;
json.x1y = 4;
json.x2y = 1;
json.x9y = 3;
exit=0
